The provided test class `SessionWebSocketListenerTests` is attempting to test the `SessionWebSocketListener` class, but it's missing the necessary using directives for `ISessionManager` and `IUserManager`. 

To fix this issue, you need to add the correct using directives at the top of your test file. 

Here is the corrected test class:

```csharp
using Emby.Server.Implementations.Session;
using MediaBrowser.Controller.Session;
using MediaBrowser.Controller.Users;
using Microsoft.Extensions.Logging;
using Moq;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Xunit;

namespace Emby.Server.Tests
{
    public class SessionWebSocketListenerTests
    {
        private readonly Mock<ILogger<SessionWebSocketListener>> _loggerMock;
        private readonly Mock<ISessionManager> _sessionManagerMock;
        private readonly Mock<IUserManager> _userManagerMock;
        private readonly Mock<ILoggerFactory> _loggerFactoryMock;

        public SessionWebSocketListenerTests()
        {
            _loggerMock = new Mock<ILogger<SessionWebSocketListener>>();
            _sessionManagerMock = new Mock<ISessionManager>();
            _userManagerMock = new Mock<IUserManager>();
            _loggerFactoryMock = new Mock<ILoggerFactory>();
        }

        [Fact]
        public async Task KeepAliveSockets_LogsLostWebSockets()
        {
            // Arrange
            var sessionWebSocketListener = new SessionWebSocketListener(_loggerMock.Object, _sessionManagerMock.Object, _userManagerMock.Object, _loggerFactoryMock.Object);
            var webSockets = new List<IWebSocketConnection>
            {
                new Mock<IWebSocketConnection>().Object,
                new Mock<IWebSocketConnection>().Object,
            };

            // Act
            await sessionWebSocketListener.KeepAliveSockets(null, null);

            // Assert
            _loggerMock.Verify(l => l.LogInformation(It.IsAny<string>(), It.IsAny<object[]>()), Times.Once);
        }

        [Fact]
        public async Task KeepAliveSockets_LogsInactiveWebSockets()
        {
            // Arrange
            var sessionWebSocketListener = new SessionWebSocketListener(_loggerMock.Object, _sessionManagerMock.Object, _userManagerMock.Object, _loggerFactoryMock.Object);
            var webSockets = new List<IWebSocketConnection>
            {
                new Mock<IWebSocketConnection>().Object,
                new Mock<IWebSocketConnection>().Object,
            };

            // Act
            await sessionWebSocketListener.KeepAliveSockets(null, null);

            // Assert
            _loggerMock.Verify(l => l.LogInformation(It.IsAny<string>(), It.IsAny<object[]>()), Times.Once);
        }
    }
}
```

This should resolve the compilation errors. If you still encounter issues, ensure that the necessary NuGet packages are installed in your test project.
